 * Errors the CLI reports on standard error. `code` is the process exit code;
 * `message` is written after the `error: ` prefix.
 */
export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

/** A parse or validation failure: reported with exit code 2. */
export class UsageError extends CliError {
  constructor(message) {
    super(message, 2)
  }
}

/** A dependency cycle: reported with exit code 3. */
export class CycleError extends CliError {
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`, 3)
  }
}
"}

