const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build-graph text format into a graph: a map of task name to
 * cost and a map of task name to its unique dependency names, in the order
 * first listed. Throws `UsageError` for any syntax or semantic problem
 * other than a dependency cycle.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const costs = new Map()
  const declaredAtLine = new Map()
  const deps = new Map()
  const referencedInOrder = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new UsageError(`line ${lineNumber}: expected task <name> <cost>`)
      }
      const [, name, costText] = words
      if (!NAME_RE.test(name)) {
        throw new UsageError(`line ${lineNumber}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costText)) {
        throw new UsageError(`line ${lineNumber}: cost must be a non-negative integer`)
      }
      if (declaredAtLine.has(name)) {
        throw new UsageError(`line ${lineNumber}: task ${name} is declared twice`)
      }
      declaredAtLine.set(name, lineNumber)
      costs.set(name, parseInt(costText, 10))
      if (!deps.has(name)) deps.set(name, [])
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new UsageError(`line ${lineNumber}: expected dep <name> <dependency>...`)
      }
      const [, name, ...dependencies] = words
      for (const candidate of [name, ...dependencies]) {
        if (!NAME_RE.test(candidate)) {
          throw new UsageError(`line ${lineNumber}: invalid task name ${candidate}`)
        }
      }
      referencedInOrder.push(name, ...dependencies)
      if (!deps.has(name)) deps.set(name, [])
      const existing = deps.get(name)
      for (const dependency of dependencies) {
        if (!existing.includes(dependency)) existing.push(dependency)
      }
    } else {
      throw new UsageError(`line ${lineNumber}: unknown directive ${directive}`)
    }
  }

  for (const name of referencedInOrder) {
    if (!costs.has(name)) {
      throw new UsageError(`unknown task ${name}`)
    }
  }

  return { costs, deps }
}
"}

