/**
 * Finds a dependency cycle, if one exists, by running a depth-first search
 * from each task in ascending name order, walking each task's dependencies
 * in ascending name order. Returns the names from the re-entered task,
 * through the search stack, back to that task, or `null` if the graph is
 * acyclic.
 */
function findCycle(costs, deps) {
  const names = [...costs.keys()].sort()
  const state = new Map(names.map((name) => [name, 0])) // 0 unvisited, 1 in stack, 2 done
  const stack = []

  for (const start of names) {
    if (state.get(start) !== 0) continue

    const frames = [{ name: start, sorted: [...deps.get(start)].sort(), index: 0 }]
    state.set(start, 1)
    stack.push(start)

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.index < frame.sorted.length) {
        const next = frame.sorted[frame.index++]
        const nextState = state.get(next)
        if (nextState === 1) {
          const position = stack.indexOf(next)
          return stack.slice(position).concat(next)
        } else if (nextState === 0) {
          state.set(next, 1)
          stack.push(next)
          frames.push({ name: next, sorted: [...deps.get(next)].sort(), index: 0 })
        }
      } else {
        state.set(frame.name, 2)
        stack.pop()
        frames.pop()
      }
    }
  }

  return null
}

/**
 * Builds the schedule shared by `waves` and `explain`: for each task, the
 * start (the greatest finish among its dependencies, or 0), the finish
 * (start plus cost) and the depth (the wave it sits in). Throws
 * `CycleError` if the graph has a cycle.
 */
export function buildSchedule(costs, deps) {
  const cycle = findCycle(costs, deps)
  if (cycle) throw new CycleError(cycle)

  const names = [...costs.keys()]
  const dependents = new Map(names.map((name) => [name, []]))
  const indegree = new Map()
  for (const name of names) indegree.set(name, deps.get(name).length)
  for (const name of names) {
    for (const dependency of deps.get(name)) dependents.get(dependency).push(name)
  }

  const start = new Map(names.map((name) => [name, 0]))
  const finish = new Map()
  const depth = new Map(names.map((name) => [name, 0]))

  const queue = names.filter((name) => indegree.get(name) === 0)
  while (queue.length > 0) {
    const name = queue.shift()
    finish.set(name, start.get(name) + costs.get(name))
    for (const dependent of dependents.get(name)) {
      start.set(dependent, Math.max(start.get(dependent), finish.get(name)))
      depth.set(dependent, Math.max(depth.get(dependent), depth.get(name) + 1))
      indegree.set(dependent, indegree.get(dependent) - 1)
      if (indegree.get(dependent) === 0) queue.push(dependent)
    }
  }

  return { start, finish, depth, dependents }
}

/** Groups tasks by depth for the `waves` and `explain` commands. */
export function computeWaves(costs, deps) {
  const { start, finish, depth } = buildSchedule(costs, deps)
  const names = [...costs.keys()].sort()
  const waveCount = names.reduce((max, name) => Math.max(max, depth.get(name) + 1), 0)
  const waves = []
  for (let k = 0; k < waveCount; k++) waves.push([])
  for (const name of names) waves[depth.get(name)].push(name)
  const total = names.reduce((max, name) => Math.max(max, finish.get(name)), 0)
  return { waves, start, finish, depth, total }
}

/**
 * Simulates the graph on a fixed number of workers. At every instant, while
 * a worker is free and a task is ready, the ready task with the greatest
 * priority (the cost of the longest chain starting at it, counting its own
 * cost and the costs of its dependents down to a task nothing depends on)
 * is started on the free worker with the smallest index, breaking priority
 * ties by ascending name.
 */
export function computePack(costs, deps, workerCount) {
  const { dependents } = buildSchedule(costs, deps)
  const names = [...costs.keys()]

  // Priority: cost of the longest chain starting at each task and running
  // through its dependents. Computed by processing tasks after all of their
  // dependents (a reverse topological order over the dependency graph).
  const indegree = new Map()
  for (const name of names) indegree.set(name, deps.get(name).length)
  const forwardOrder = []
  const queue = names.filter((name) => indegree.get(name) === 0)
  while (queue.length > 0) {
    const name = queue.shift()
    forwardOrder.push(name)
    for (const dependent of dependents.get(name)) {
      indegree.set(dependent, indegree.get(dependent) - 1)
      if (indegree.get(dependent) === 0) queue.push(dependent)
    }
  }

  const priority = new Map()
  for (let i = forwardOrder.length - 1; i >= 0; i--) {
    const name = forwardOrder[i]
    let downstream = 0
    for (const dependent of dependents.get(name)) downstream = Math.max(downstream, priority.get(dependent))
    priority.set(name, costs.get(name) + downstream)
  }

  const remainingDeps = new Map()
  for (const name of names) remainingDeps.set(name, deps.get(name).length)
  const readyAt = new Map()
  let ready = []
  for (const name of names) {
    if (remainingDeps.get(name) === 0) {
      readyAt.set(name, 0)
      ready.push(name)
    }
  }

  const workers = Array.from({ length: workerCount }, () => ({ nextFree: 0, runs: [] }))
  let scheduled = 0
  let t = 0
  let makespan = 0

  while (scheduled < names.length) {
    for (;;) {
      const worker = workers.find((w) => w.nextFree <= t)
      if (!worker) break
      const actionable = ready.filter((name) => readyAt.get(name) <= t)
      if (actionable.length === 0) break

      actionable.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : a > b ? 1 : 0))
      const chosen = actionable[0]
      ready = ready.filter((name) => name !== chosen)

      const taskFinish = t + costs.get(chosen)
      worker.runs.push({ name: chosen, start: t, finish: taskFinish })
      worker.nextFree = taskFinish
      makespan = Math.max(makespan, taskFinish)
      scheduled++

      for (const dependent of dependents.get(chosen)) {
        remainingDeps.set(dependent, remainingDeps.get(dependent) - 1)
        if (remainingDeps.get(dependent) === 0) {
          readyAt.set(dependent, taskFinish)
          ready.push(dependent)
        }
      }
    }

    if (scheduled >= names.length) break

    let next = Infinity
    for (const worker of workers) if (worker.nextFree > t) next = Math.min(next, worker.nextFree)
    for (const name of ready) if (readyAt.get(name) > t) next = Math.min(next, readyAt.get(name))
    t = next
  }

  return { workers, makespan }
}
"}

