  const stack = []

  for (const start of names) {
    if (state.get(start) !== 0) continue

    const frames = [{ name: start, sorted: [...deps.get(start)].sort(), index: 0 }]
    state.set(start, 1)
    stack.push(start)

    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.index < frame.sorted.length) {
        const next = frame.sorted[frame.index++]
        const nextState = state.get(next)
        if (nextState === 1) {
          const position = stack.indexOf(next)
          return stack.slice(position).concat(next)
        } else if (nextState === 0) {
          state.set(next, 1)
          stack.push(next)
          frames.push({ name: next, sorted: [...deps.get(next)].sort(), index: 0 })
