  const args = parseArgs(argv)
  const { costs, deps } = parseGraph(input)

  if (args.mode === 'waves') {
    const { waves, total } = computeWaves(costs, deps)
    const lines = waves.map((names, k) => `wave ${k}: ${names.join(' ')}`)
    lines.push(`total ${total}`)
    return lines.join('\n') + '\n'
  }

  if (args.mode === 'explain') {
    const { start, finish, depth, total } = computeWaves(costs, deps)
    const names = [...costs.keys()].sort()
    const lines = names.map(
      (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
    )
    lines.push(`total ${total}`)
    return lines.join('\n') + '\n'
  }

