import { readFileSync } from 'node:fs'
import { CliError, UsageError } from './errors.js'
import { parseGraph } from './parse.js'
import { computePack, computeWaves } from './graph.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new UsageError('workers must be a positive integer')
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new UsageError(USAGE)
}

function run(argv, input) {
  const args = parseArgs(argv)
  const { costs, deps } = parseGraph(input)

  if (args.mode === 'waves') {
    const { waves, total } = computeWaves(costs, deps)
    const lines = waves.map((names, k) => `wave ${k}: ${names.join(' ')}`)
    lines.push(`total ${total}`)
    return lines.join('\n') + '\n'
  }

  if (args.mode === 'explain') {
    const { start, finish, depth, total } = computeWaves(costs, deps)
    const names = [...costs.keys()].sort()
    const lines = names.map(
      (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
    )
    lines.push(`total ${total}`)
    return lines.join('\n') + '\n'
  }

  const { workers, makespan } = computePack(costs, deps, args.workers)
  const lines = workers.map((worker, i) => {
    const runs = worker.runs.map((r) => ` ${r.name}@${r.start}-${r.finish}`).join('')
    return `worker ${i}:${runs}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const input = readFileSync(0, 'utf8')
  try {
    const output = run(process.argv.slice(2), input)
    process.stdout.write(output)
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(err.code)
    }
    throw err
  }
}

